"""
    A binary half adder -- performing addition only using logic operators,
    A half adder simply adds two bits and outputs a sum and carry
    """
def half_adder(a: Any, b: Any) -> object {
    sum = a ^ b;
    carry = a and b;
    return (carry, sum);
}

test_blocks:
test "t0" {
    assert (half_adder(False, True) == (False, True));;
}

test "t1" {
    assert (half_adder(1, 1) == (1, 0));;
}

test "t2" {
    assert (half_adder(False, False) == (False, False));;
}

test "t3" {
    assert (half_adder(0, 1) == (0, 1));;
}

